  "cloud-native-assign-day-3": "const r = [{ destination: '10.0.0.0/16', target: 'local' }, { destination: '0.0.0.0/0', target: 'igw-123' }];\nif (hasInternetGatewayRoute(r) !== true) throw new Error('IGW check failed');",
