  "cloud-native-assign-day-5": "if (areSubnetsDistinct([{ cidr: '10.0.1.0/24' }, { cidr: '10.0.1.0/24' }]) !== false) throw new Error('Duplicate CIDR should fail');",
  "cloud-native-assign-day-6": "const p = parseArn('arn:aws:s3:us-east-1:123456789012:bucket/key');\nif (p.service !== 's3' || p.region !== 'us-east-1') throw new Error('ARN parser failed');",
