  "comp_fund-assign-day-22": "if (getLinuxContainerResourceControl() !== 'CONTROL_GROUPS_CGROUPS') throw new Error('Cgroups check failed');",
  "comp_fund-assign-day-23": "if (getFinalTroubleshootingStep() !== 'DOCUMENT_FINDINGS_ACTIONS_AND_ROOT_CAUSE') throw new Error('Step check failed');",
