  "design-assign-day-5": "if (formatDesignFoundationsStatus(true) !== 'DESIGN_FOUNDATIONS_ACTIVE') throw new Error('Status check failed');",
  "design-assign-day-6": "if (getAtomicDesignPioneer() !== 'Brad Frost') throw new Error('Pioneer check failed');",
