  "excel_viz-exam-day-6": "const data = [\n  { id: 1, region: 'NORTH', amount: 500 },\n  { id: 2, region: 'NORTH', amount: 1500 },\n  { id: 3, region: 'SOUTH', amount: 2000 },\n  { id: 4, region: 'NORTH', amount: 2500 }\n];\nconst res = executeSumifs(data, 'NORTH', 1000); // 1500 + 2500 = 4000, count = 2\nif (res.matchedCount !== 2 || res.totalAmountSum !== 4000.0 || res.averageAmount !== 2000.0 || res.status !== 'SUMIFS_CONDITIONAL_AGGREGATION_COMPUTED_NOMINAL') throw new Error('SUMIFS calculation failed');",
  "excel_viz-exam-day-7": "const raw = '   john   DOE   ';\nconst res = cleanseSpreadsheetText(raw);\nif (res.cleansedText !== 'John Doe' || res.spacesRemovedCount <= 0 || res.status !== 'TEXT_CLEANSED_PROPER_CASE_NOMINAL') throw new Error('Text cleansing failed');",
