  "excel_viz-exam-day-9": "const db = [{ id: 101, name: 'Alice', role: 'Engineer' }, { id: 102, name: 'Bob', role: 'Designer' }];\nconst res = executeVlookup(db, 101, 'role');\nconst fail = executeVlookup(db, 999, 'role');\nif (!res.found || res.result !== 'Engineer' || fail.found || fail.result !== '#N/A') throw new Error('VLOOKUP failed');",
  "fizzbuzz": "\n    if (typeof fizzBuzz !== 'function') throw new Error(\"Method fizzBuzz(int n) not found.\");\n    if (fizzBuzz(3) !== \"Fizz\") throw new Error(\"Failed: fizzBuzz(3) should return 'Fizz'\");\n    if (fizzBuzz(5) !== \"Buzz\") throw new Error(\"Failed: fizzBuzz(5) should return 'Buzz'\");\n    if (fizzBuzz(15) !== \"FizzBuzz\") throw new Error(\"Failed: fizzBuzz(15) should return 'FizzBuzz'\");\n    if (fizzBuzz(7) !== \"7\") throw new Error(\"Failed: fizzBuzz(7) should return '7'\");\n    if (fizzBuzz(1) !== \"1\") throw new Error(\"Failed: fizzBuzz(1) should return '1'\");\n  ",
  "fullstack-js-assign-day-1": "const secretCfg = { appName: 'PinIT', apiUrl: 'https://api.pinit.io', jwtSecret: 'super-secret', dbPassword: 'root' };\nconst clean = sanitizeClientConfig(secretCfg);\nif (clean.jwtSecret || clean.dbPassword || clean.appName !== 'PinIT') throw new Error('Private secrets leaked to client');",
