  "mobile-assign-day-11": "if (getOpenSettingsMethod() !== 'Linking.openSettings') throw new Error('Method check failed');",
  "mobile-assign-day-12": "if (getStandardGpsAccuracyThreshold() !== 20) throw new Error('Threshold check failed');",
  "mobile-assign-day-13": "if (getAppleBiometricName() !== 'FaceID') throw new Error('Biometric name check failed');",
  "mobile-assign-day-14": "if (getSqliteVersionPragma() !== 'PRAGMA user_version') throw new Error('Pragma check failed');",
  "mobile-assign-day-15": "if (getNativeCapabilitiesMasterStatus() !== 'NATIVE_CAPABILITIES_MASTER_ACTIVE') throw new Error('Status check failed');",
