  "react-basics-exam-day-7": "if (typeof buildUseToggleState !== 'function') throw new Error('buildUseToggleState not found');\nconst t = buildUseToggleState(false);\nt.toggle();\nif (t.value !== true) throw new Error('Toggle failed');\nt.setFalse();\nif (t.value !== false) throw new Error('setFalse failed');",
  "react-basics-exam-day-8": "if (typeof resolveUserTheme !== 'function') throw new Error('resolveUserTheme not found');\nconst t = resolveUserTheme(null, { mode: 'dark', color: '#6366f1' });\nif (t.mode !== 'dark' || t.primaryColor !== '#6366f1') throw new Error('Theme fallback failed');",
  "react-basics-exam-day-9": "if (typeof isModalAttached !== 'function') throw new Error('isModalAttached not found');\nconst reg = { 'auth-modal': { isMounted: true, target: 'body' } };\nif (!isModalAttached(reg, 'auth-modal')) throw new Error('Portal check failed');\nif (isModalAttached(reg, 'nonexistent')) throw new Error('False positive on unmounted modal');",
  "reverser": "\n    if (typeof reverseString !== 'function') throw new Error(\"Method reverseString(String s) not found.\");\n    if (reverseString(\"hello\") !== \"olleh\") throw new Error(\"Failed: reverseString('hello') !== 'olleh'\");\n    if (reverseString(\"\") !== \"\") throw new Error(\"Failed: reverseString('') should return ''\");\n    if (reverseString(\"a\") !== \"a\") throw new Error(\"Failed: reverseString('a') !== 'a'\");\n    if (reverseString(\"abcde\") !== \"edcba\") throw new Error(\"Failed: reverseString('abcde') !== 'edcba'\");\n  ",
